window.RTLBenchLSData.register("assets/d385719b16078f4b49fa54f19bd205fc759bc053e0a0203a83d091f545b2d3f8.txt","module origen_046595 (\n    input wire CLK,\n    input wire RST,\n    input wire VALID,\n    input wire [2:0] ROM_ADDR,\n    output reg CLR_CRC,\n    output reg CRC_CALC,\n    output reg CRC_VLD,\n    output reg INC_ROM,\n    output reg RST_ROM_OUT,\n    output reg TX_ACK_OUT,\n    output reg [2:0] FRM_STATE\n);\n\n    // State encoding\n    localparam [2:0] \n        IDLE     = 3'b000,\n        PREAMBLE = 3'b001,\n        TX_ACK   = 3'b010,\n        DATA     = 3'b011,\n        CRC_EOP  = 3'b100,\n        RST_ROM  = 3'b101;\n\n    reg [2:0] current_state, next_state;\n\n    // State register\n    always @(posedge CLK or posedge RST) begin\n        if (RST)\n            current_state <= IDLE;\n        else\n            current_state <= next_state;\n    end\n\n    // Next state logic\n    always @(*) begin\n        case (current_state)\n            IDLE:     next_state = VALID ? PREAMBLE : IDLE;\n            PREAMBLE: next_state = (ROM_ADDR == 3'd4) ? TX_ACK : PREAMBLE;\n            TX_ACK:   next_state = DATA;\n            DATA:     next_state = VALID ? DATA : CRC_EOP;\n            CRC_EOP:  next_state = (ROM_ADDR == 3'd7) ? RST_ROM : CRC_EOP;\n            RST_ROM:  next_state = IDLE;\n            default:  next_state = IDLE;\n        endcase\n    end\n\n    // Output logic\n    always @(*) begin\n        // Default output values\n        CLR_CRC  = 1'b0;\n        CRC_CALC = 1'b0;\n        CRC_VLD  = 1'b0;\n        INC_ROM  = 1'b0;\n        RST_ROM_OUT  = 1'b0;\n        TX_ACK_OUT   = 1'b0;\n        FRM_STATE = current_state;\n\n        case (current_state)\n            IDLE: begin\n                if (VALID) INC_ROM = 1'b1;\n            end\n            PREAMBLE: begin\n                CLR_CRC = (ROM_ADDR == 3'd0);\n                INC_ROM = 1'b1;\n            end\n            TX_ACK: begin\n                TX_ACK_OUT = 1'b1;\n            end\n            DATA: begin\n                if (VALID) CRC_CALC = 1'b1;\n            end\n            CRC_EOP: begin\n                CRC_VLD = 1'b1;\n                INC_ROM = 1'b1;\n            end\n            RST_ROM: begin\n                RST_ROM_OUT = 1'b1;\n            end\n        endcase\n    end\n\n    // Debugging: State name (non-synthesizable)\n    reg [63:0] statename;\n    always @(*) begin\n        case (current_state)\n            IDLE:     statename = \"IDLE\";\n            PREAMBLE: statename = \"PREAMBLE\";\n            TX_ACK:   statename = \"TX_ACK\";\n            DATA:     statename = \"DATA\";\n            CRC_EOP:  statename = \"CRC_EOP\";\n            RST_ROM:  statename = \"RST_ROM\";\n            default:  statename = \"UNKNOWN\";\n        endcase\n    end\n\nendmodule");
